CREATE OR REPLACE FUNCTION public.contact_field_allowed(_owner uuid,_field text,_vehicle boolean DEFAULT false) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(public.has_role(auth.uid(),'admin'),false) OR (auth.uid() IS NOT NULL AND NOT public.chat_only_viewer() AND (NOT _vehicle OR public.has_paid_bell(auth.uid())) AND EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=_owner AND public.account_allowed(p.id) AND p.public_bell_consent AND CASE _field WHEN 'name' THEN NOT coalesce(p.hide_name,true) WHEN 'phone' THEN NOT coalesce(p.hide_phone,true) WHEN 'photo' THEN NOT coalesce(p.hide_photo,true) ELSE false END)) $$;
DO $$ DECLARE f text; sig text; owner_expr text; field text; alias text; vehicle_expr text; BEGIN
 FOREACH sig IN ARRAY ARRAY['public.list_vehicle_bell_contacts(text,text)','public.list_free_work_interest_contacts(text,text,text)'] LOOP
 f:=pg_get_functiondef(sig::regprocedure); owner_expr:=CASE WHEN sig LIKE '%list_vehicle%' THEN 'd.user_id' ELSE 'i.user_id' END; vehicle_expr:=CASE WHEN sig LIKE '%list_vehicle%' THEN 'true' ELSE 'false' END;
 FOREACH field IN ARRAY ARRAY['name','phone','photo'] LOOP f:=replace(f,'coalesce(pr.hide_'||field||',true)', 'NOT public.contact_field_allowed('||owner_expr||','''||field||''','||vehicle_expr||')'); END LOOP; EXECUTE f; END LOOP;
 FOREACH sig IN ARRAY ARRAY['public.list_post_bell_contacts(uuid)','public.my_incoming_bell_contacts(text,uuid)','public.chat_peer_identity(uuid)'] LOOP
 f:=pg_get_functiondef(sig::regprocedure); alias:=CASE WHEN sig LIKE '%list_post%' THEN 'pr' ELSE 'p' END; vehicle_expr:=CASE WHEN sig LIKE '%list_post%' THEN 'EXISTS(SELECT 1 FROM public.posts cp WHERE cp.id=b.post_id AND cp.module=''vehicle'')' WHEN sig LIKE '%my_incoming%' THEN '_section IN (''goods'',''returns'',''cars'')' ELSE 'false' END;
 FOREACH field IN ARRAY ARRAY['name','phone','photo'] LOOP
 f:=replace(f,alias||'.hide_'||field||' AND NOT public.has_role(auth.uid(),''admin'')', 'NOT public.contact_field_allowed('||alias||'.id,'''||field||''','||vehicle_expr||')');
 f:=replace(f,alias||'.hide_'||field||' AND NOT a.admin', 'NOT public.contact_field_allowed('||alias||'.id,'''||field||''','||vehicle_expr||')');
 END LOOP; EXECUTE f; END LOOP;
 f:=pg_get_functiondef('public.get_post_details(uuid)'::regprocedure);
 f:=replace(f,'contact AND NOT coalesce(pr.hide_name, false)', 'contact AND public.contact_field_allowed(pr.id,''name'',p.module=''vehicle'')');
 f:=replace(f,'contact AND NOT coalesce(pr.hide_phone, false)', 'contact AND public.contact_field_allowed(pr.id,''phone'',p.module=''vehicle'')');
 f:=replace(f,'contact AND NOT coalesce(pr.hide_photo, false)', 'contact AND public.contact_field_allowed(pr.id,''photo'',p.module=''vehicle'')');
 f:=replace(f,'''public_brand'', CASE WHEN contact THEN', '''public_brand'', CASE WHEN allow_name THEN');
 EXECUTE f;
END $$;
CREATE OR REPLACE FUNCTION public.public_bell_photo_allowed(_path text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.profiles pr WHERE pr.photo_path=_path AND public.contact_field_allowed(pr.id,'photo',false) AND (EXISTS(SELECT 1 FROM public.free_work_interests i WHERE i.user_id=pr.id AND i.created_at+interval '30 days'>now()) OR (public.has_paid_bell(auth.uid()) AND EXISTS(SELECT 1 FROM public.posts po WHERE public.post_listing_visible(po) AND (EXISTS(SELECT 1 FROM public.post_bell_interests i WHERE i.post_id=po.id AND i.user_id=pr.id) OR EXISTS(SELECT 1 FROM public.vehicle_bell_demands d WHERE d.post_id=po.id AND d.user_id=pr.id)))))) $$;
CREATE OR REPLACE FUNCTION public.vehicle_post_photo_allowed(_path text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND (split_part(_path,'/',1)=auth.uid()::text OR public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.posts p WHERE p.vehicle_photo_path=_path AND p.module='vehicle' AND p.show_contact AND public.post_listing_visible(p) AND public.contact_field_allowed(p.user_id,'photo',true))) $$;
CREATE POLICY profile_photo_authoritative_hide ON storage.objects AS RESTRICTIVE FOR SELECT TO anon,authenticated USING (bucket_id<>'profile-photos' OR (auth.uid() IS NOT NULL AND (split_part(name,'/',1)=auth.uid()::text OR public.has_role(auth.uid(),'admin') OR public.public_bell_photo_allowed(name))));
CREATE OR REPLACE FUNCTION public.service_profile_data(_id uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN p.published OR p.user_id=auth.uid() THEN jsonb_build_object('profile',to_jsonb(p)||jsonb_build_object('display_name',CASE WHEN public.contact_field_allowed(p.user_id,'name') THEN p.display_name ELSE '' END,'photo_path',CASE WHEN public.contact_field_allowed(p.user_id,'photo') THEN p.photo_path ELSE '' END),'photos',coalesce((SELECT jsonb_agg(to_jsonb(f)) FROM public.service_photos f WHERE f.user_id=p.user_id),'[]'::jsonb),'reviews',coalesce((SELECT jsonb_agg(jsonb_build_object('id',r.id,'rating',r.rating,'body',r.body,'created_at',r.created_at,'author_name','','author_photo','','author_public_id',NULL) ORDER BY r.created_at DESC) FROM public.service_reviews r WHERE r.profile_id=p.user_id),'[]'::jsonb),'likes',(SELECT count(*) FROM public.service_likes l WHERE l.profile_id=p.user_id),'views',(SELECT count(*) FROM public.service_views v WHERE v.profile_id=p.user_id)) ELSE NULL END FROM public.service_profiles p WHERE p.user_id=_id $$;
-- Raw phone columns are not readable by ordinary clients, even for previously sent messages.
REVOKE SELECT ON public.messages FROM anon,authenticated;
DO $$ DECLARE cols text; BEGIN SELECT string_agg(quote_ident(column_name),',') INTO cols FROM information_schema.columns WHERE table_schema='public' AND table_name='messages' AND column_name<>'chat_phone'; EXECUTE 'GRANT SELECT ('||cols||') ON public.messages TO authenticated'; END $$;
REVOKE SELECT(chat_phone) ON public.messages FROM anon,authenticated;
CREATE OR REPLACE FUNCTION public.list_chat_messages(_other uuid DEFAULT NULL,_post uuid DEFAULT NULL) RETURNS SETOF public.messages LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE m public.messages; admin boolean:=coalesce(public.has_role(auth.uid(),'admin'),false); BEGIN IF auth.uid() IS NULL OR NOT public.account_allowed(auth.uid()) THEN RAISE EXCEPTION 'SIGN_IN_REQUIRED'; END IF; FOR m IN SELECT x.* FROM public.messages x WHERE (admin OR x.sender_id=auth.uid() OR x.receiver_id=auth.uid()) AND (_other IS NULL OR (x.sender_id=auth.uid() AND x.receiver_id=_other) OR (x.receiver_id=auth.uid() AND x.sender_id=_other)) AND (_post IS NULL OR x.post_id=_post OR x.app_call_id IS NOT NULL) AND NOT EXISTS(SELECT 1 FROM public.dashboard_dismissals d WHERE d.user_id=auth.uid() AND d.kind='message' AND d.item_id=x.id) ORDER BY x.created_at DESC LIMIT 500 LOOP IF NOT admin AND m.sender_id<>auth.uid() AND NOT public.contact_field_allowed(m.sender_id,'phone') THEN m.chat_phone:=''; END IF; RETURN NEXT m; END LOOP; END $$;
REVOKE ALL ON FUNCTION public.list_chat_messages(uuid,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.list_chat_messages(uuid,uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.app_call_dial_number(_other uuid) RETURNS text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE ph text; BEGIN IF NOT public.can_call_member(_other) OR NOT public.contact_field_allowed(_other,'phone',true) THEN RETURN NULL; END IF; SELECT phone INTO ph FROM public.profiles WHERE id=_other AND phone ~ '^[6-9][0-9]{9}$'; RETURN ph; END $$;
CREATE OR REPLACE FUNCTION public.guard_chat_attachment() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.chat_phone<>'' AND NEW.chat_phone !~ '^[6-9][0-9]{9}$' THEN RAISE EXCEPTION 'INVALID_CHAT_PHONE'; END IF; IF NEW.image_path<>'' AND NEW.image_path NOT LIKE NEW.sender_id::text||'/%' THEN RAISE EXCEPTION 'INVALID_CHAT_IMAGE'; END IF; IF coalesce(NEW.chat_phone,'')<>'' AND NOT public.has_role(NEW.receiver_id,'admin') AND NOT public.has_role(NEW.sender_id,'admin') AND (NOT public.contact_field_allowed(NEW.sender_id,'phone') OR (public.has_paid_vehicle_chat(NEW.receiver_id) AND NOT public.has_paid_bell(NEW.receiver_id))) THEN RAISE EXCEPTION 'PHONE_HIDDEN'; END IF; RETURN NEW; END $$;